public async Task<string> GetWithTimeoutAsync(
    string url, TimeSpan timeout, CancellationToken cancellationToken)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
    cts.CancelAfter(timeout);

    var tcs = new TaskCompletionSource<string>(
        TaskCreationOptions.RunContinuationsAsynchronously, cts.Token);

    _ = FetchAndCompleteAsync(url, tcs, cts.Token);
    return await tcs.Task;
}

static async Task FetchAndCompleteAsync(
    string url, TaskCompletionSource<string> tcs, CancellationToken token)
{
    try
    {
        var data = await http.GetStringAsync(url, token);
        tcs.TrySetResult(data);
    }
    catch (Exception ex)
    {
        tcs.TrySetException(ex);
    }
}

private readonly ConcurrentDictionary<string, Task<string>> _inFlight = new();

public Task<string> GetOrLoadAsync(string key, CancellationToken cancellationToken)
{
    return _inFlight.GetOrAdd(key, static (k, state) =>
    {
        var tcs = new TaskCompletionSource<string>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        _ = LoadAndCompleteAsync(k, tcs, state.Token);
        return tcs.Task;
    }, (this, cancellationToken));
}

async Task LoadAndCompleteAsync(
    string key, TaskCompletionSource<string> tcs, CancellationToken token)
{
    try
    {
        var value = await _redis.StringGetAsync(key);
        tcs.TrySetResult(value.ToString()!);
    }
    finally
    {
        _inFlight.TryRemove(key, out _);
    }
}

// WRONG — second call throws InvalidOperationException
var tcs = new TaskCompletionSource<int>();
tcs.SetResult(1);
tcs.SetResult(2); // throws!

// RIGHT — racing callbacks use TrySet
void OnTimeout() => tcs.TrySetCanceled();
void OnSuccess(int n) => tcs.TrySetResult(n);
// Only the first caller wins; the other returns false
